def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-1] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                j2 = i1 + j1 - i2
                if j2 < 0 or j2 >= N or grid[i1][j1] == 0 or grid[i2][j2] == 0:
                    continue
                if i1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1-1][j1][i2])
                if j1 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1-1][i2])
                if i2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2-1])
                if j2 > 0:
                    dp[i1][j1][i2] = max(dp[i1][j1][i2], dp[i1][j1][i2][j2-1])
                if dp[i1][j1][i2] != -1:
                    if i1 == i2 and j1 == j2:
                        dp[i1][j1][i2] += grid[i1][j1]
                    else:
                        dp[i1][j1][i2] += grid[i1][j1] + grid[i2][j2]

    return max(0, dp[N-1][N-1][N-1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 3D DP table with dimensions (N+1) x (N+1) x (N+1)
    # dp[i][j][k] will store the maximum value collected by two paths
    # where one path is at (i, j) and the other is at (i, k)
    dp = [[[-1 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]

    # Initialize the grid with the given values
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # Base case: starting point
    dp[1][1][1] = grid[1][1]

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                l = i + j - k
                if l < 1 or l > N:
                    continue
                if dp[i][j][k] == -1:
                    val1, val2 = 0, 0
                    # Collect values from previous steps
                    if i > 1 and j > 1:
                        val1 = dp[i-1][j-1][k]
                    if i > 1 and k > 1:
                        val1 = max(val1, dp[i-1][j][k-1])
                    if i > 1:
                        val1 = max(val1, dp[i-1][j][k])
                    if j > 1 and k > 1:
                        val2 = dp[i][j-1][k-1]
                    if j > 1:
                        val2 = max(val2, dp[i][j-1][k])
                    if k > 1:
                        val2 = max(val2, dp[i][j][k-1])

                    # If both paths are at the same cell, don't double count
                    if j == k and i == l:
                        dp[i][j][k] = max(val1, val2) + grid[i][j]
                    else:
                        dp[i][j][k] = max(val1, val2) + grid[i][j] + grid[l][k]

    # The result is the maximum value collected by reaching the bottom-right corner
    return dp[N][N][N]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    import numpy as np

    # Initialize the grid with zeros
    grid = np.zeros((N, N), dtype=int)

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1, y-1] = value

    # Initialize a 4D DP array
    dp = -np.ones((N, N, N, N), dtype=int)
    dp[0, 0, 0, 0] = grid[0, 0]

    # Fill the DP table
    for i1 in range(N):
        for j1 in range(N):
            for i2 in range(N):
                for j2 in range(N):
                    if dp[i1, j1, i2, j2] == -1:
                        continue

                    val1 = grid[i1, j1]
                    val2 = grid[i2, j2]

                    if i1 == i2 and j1 == j2:
                        current_value = val1
                    else:
                        current_value = val1 + val2

                    # Move first path down
                    if i1 + 1 < N:
                        dp[i1 + 1, j1, i2, j2] = max(dp[i1 + 1, j1, i2, j2], dp[i1, j1, i2, j2] + current_value)

                    # Move first path right
                    if j1 + 1 < N:
                        dp[i1, j1 + 1, i2, j2] = max(dp[i1, j1 + 1, i2, j2], dp[i1, j1, i2, j2] + current_value)

                    # Move second path down
                    if i2 + 1 < N:
                        dp[i1, j1, i2 + 1, j2] = max(dp[i1, j1, i2 + 1, j2], dp[i1, j1, i2, j2] + current_value)

                    # Move second path right
                    if j2 + 1 < N:
                        dp[i1, j1, i2, j2 + 1] = max(dp[i1, j1, i2, j2 + 1], dp[i1, j1, i2, j2] + current_value)

                    # Move both paths down
                    if i1 + 1 < N and i2 + 1 < N:
                        dp[i1 + 1, j1, i2 + 1, j2] = max(dp[i1 + 1, j1, i2 + 1, j2], dp[i1, j1, i2, j2] + current_value)

                    # Move first path down, second path right
                    if i1 + 1 < N and j2 + 1 < N:
                        dp[i1 + 1, j1, i2, j2 + 1] = max(dp[i1 + 1, j1, i2, j2 + 1], dp[i1, j1, i2, j2] + current_value)

                    # Move first path right, second path down
                    if j1 + 1 < N and i2 + 1 < N:
                        dp[i1, j1 + 1, i2 + 1, j2] = max(dp[i1, j1 + 1, i2 + 1, j2], dp[i1, j1, i2, j2] + current_value)

                    # Move both paths right
                    if j1 + 1 < N and j2 + 1 < N:
                        dp[i1, j1 + 1, i2, j2 + 1] = max(dp[i1, j1 + 1, i2, j2 + 1], dp[i1, j1, i2, j2] + current_value)

    return dp[N-1, N-1, N-1, N-1] if dp[N-1, N-1, N-1, N-1] != -1 else 0

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid initialized with zeros
    grid = [[0] * (N + 1) for _ in range(N + 1)]

    # Fill the grid with the provided values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x][y] = value

    # Initialize a 4D DP array to store the maximum values collected by two paths
    dp = [[[[0] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)] for _ in range(N + 1)]

    # Fill the DP table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, i + 1):
                l = j + i - k
                if l < 1 or l > N:
                    continue
                collect_both = 0
                if i == k and j == l:
                    collect_both = grid[i][j]
                else:
                    collect_both = grid[i][j] + grid[k][l]
                dp[i][j][k][l] = max(
                    dp[i - 1][j][k - 1][l] + collect_both,  # Both move down
                    dp[i - 1][j][k][l - 1] + collect_both,   # One moves down, one moves right
                    dp[i][j - 1][k - 1][l] + collect_both,   # One moves right, one moves down
                    dp[i][j - 1][k][l - 1] + collect_both    # Both move right
                )

    return dp[N][N][N][N]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a 2D grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the provided values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Create a 4D DP table to store the maximum sum of values collected
    dp = [[[[0 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]

    # Initialize the DP table
    for i in range(N+1):
        for j in range(N+1):
            for k in range(i, N+1):
                for l in range(j, N+1):
                    if i == 1 and j == 1 and k == 1 and l == 1:
                        dp[i][j][k][l] = grid[0][0]
                    else:
                        dp[i][j][k][l] = -float('inf')

    # Fill the DP table using bottom-up dynamic programming
    for i in range(1, N+1):
        for j in range(1, N+1):
            for k in range(1, N+1):
                for l in range(1, N+1):
                    if i == j and k == l:
                        if i == 1 and k == 1:
                            continue
                        dp[i][j][k][l] = max(dp[i-1][j][k-1][l], dp[i][j-1][k][l-1]) + grid[i-1][j-1]
                    else:
                        dp[i][j][k][l] = max(dp[i-1][j][k][l], dp[i][j-1][k][l], dp[i][j][k-1][l], dp[i][j][k][l-1]) + grid[i-1][j-1] + grid[k-1][l-1]

    return max(dp[N][N][N][N], 0)

def find_number_combinations():
    def digits_unique(n1, n2, n3):
        str_n1, str_n2, str_n3 = str(n1), str(n2), str(n3)
        combined = str_n1 + str_n2 + str_n3
        return len(set(combined)) == len(combined) and all(d in '123456789' for d in combined)

    result = []
    for num1 in range(123, 334):  # 334 because 3 * 334 = 1002, which is a 4-digit number
        num2 = 2 * num1
        num3 = 3 * num1
        if num2 > 999 or num3 > 999:
            break
        if digits_unique(num1, num2, num3):
            result.append((num1, num2, num3))
    return sorted(result)

def find_number_combinations():
