def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        numerator = N
        denominator = level - N + 1
    else:
        numerator = level - N + 1
        denominator = N
    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    k = 1
    while N > 0:
        if N <= k:
            if k % 2 == 0:
                return f"{N}/{k - N + 1}"
            else:
                return f"{k - N + 1}/{N}"
        N -= k
        k += 1

def max_product(num_str: str, N: int, K: int) -> int:
    def get_max_productUtil(num_arr, num_str, K, ind, N, dp):
        if ind == N:
            return 0

        if dp[ind][K] != -1:
            return dp[ind][K]

        ans = 0
        cur = 0
        for i in range(ind, N):
            cur = cur * 10 + num_arr[i]
            if K > 0:
                ans = max(ans, cur * get_max_productUtil(num_arr, num_str, K - 1, i + 1, N, dp))
            elif i == N - 1:
                ans = max(ans, cur)

        dp[ind][K] = ans
        return ans

    num_arr = [int(digit) for digit in num_str]
    dp = [[-1 for _ in range(K + 1)] for _ in range(N + 1)]
    return get_max_productUtil(num_arr, num_str, K, 0, N, dp)

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, end, k):
        if k == 0:
            return int(num_str[start:end+1])
        max_val = 0
        for i in range(start, end + 1 - k):
            left = int(num_str[start:i+1])
            right = helper(i + 1, end, k - 1)
            max_val = max(max_val, left * right)
        return max_val

    return helper(0, N - 1, K)

def max_product(num_str: str, N: int, K: int) -> int:
    def max_product_helper(start, end, k):
        if k == 0:
            return int(num_str[start:end+1])
        max_prod = 0
        for i in range(start, end - k + 1):
            current = int(num_str[start:i+1]) * max_product_helper(i+1, end, k-1)
            max_prod = max(max_prod, current)
        return max_prod

    return max_product_helper(0, N-1, K)

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, splits):
        if splits == 0:
            return int(num_str[start:])
        max_val = 0
        for i in range(start + 1, N - (splits - 1)):
            current = int(num_str[start:i])
            remaining = helper(i, splits - 1)
            max_val = max(max_val, current * remaining)
        return max_val

    return helper(0, K)

