        total += sum((int(part2[i]) * (i + 4) for i in range(3)))
        total += sum((int(part3[i]) * (i + 7) for i in range(5)))

        # Calculate the checksum digit
        checksum_digit = total % 11
        if checksum_digit == 10:
            return 'X'
        else:
            return str(checksum_digit)

    # Split the ISBN into parts
    parts = isbn.split('-')
    if len(parts) != 4:
        return "Invalid Format"

    # Extract and prepare parts
    part1, part2, part3, checksum = parts
    if len(part1) != 1 or len(part2) != 3 or len(part3) != 5:
        return "Invalid Format"

    # Calculate the correct checksum
    correct_checksum = calculate_checksum(parts[:-1])

    # Verify the ISBN
    if checksum.upper() == correct_checksum:
        return "Right"
    else:
        return f"{part1}-{part2}-{part3}-{correct_checksum}"

def verify_isbn(isbn: str) -> str:
    # Remove hyphens from the ISBN
    parts = isbn.split('-')
    isbn_digits = ''.join(parts[:-1]) + parts[-1].replace('X', '10')

    # Calculate the expected checksum
    total = 0
    for i, digit in enumerate(isbn_digits[:-1]):
        total += int(digit) * (10 - i)

    # Determine what the last character should be
    expected_checksum = 11 - (total % 11)
    if expected_checksum == 10:
        expected_checksum_char = 'X'
    elif expected_checksum == 11:
        expected_checksum_char = '0'
    else:
        expected_checksum_char = str(expected_checksum)

    # Check if the provided checksum matches the expected one
    if parts[-1] == expected_checksum_char:
        return "Right"
    else:
        # Replace the last character with the correct checksum
        correct_isbn = '-'.join(parts[:-1]) + expected_checksum_char
        return correct_isbn

