    n = len(beads)
    beads = [1] + beads + [1]  # Add 1 to the start and end to handle circular nature
    dp = [[0] * (n + 2) for _ in range(n + 2)]

    for length in range(2, n + 2):  # length of the substring, minimum is 3 (including the padding 1s)
        for i in range(1, n + 2 - length + 1):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    return dp[1][n + 1]

def max_energy(beads):
    n = len(beads)
    if n < 2:
        return 0

    # Extend the beads array to handle circular property
    beads = beads + beads

    # dp[i][j] will store the maximum energy we can get from merging beads[i] to beads[j]
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    # Fill the dp table
    for length in range(2, n + 1):  # length of the subarray
        for i in range(n):
            j = i + length - 1
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    # The result is the maximum value of dp[i][i + n - 1] for all i
    return max(dp[i][i + n - 1] for i in range(n))

