def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or k == 0:
        return 0
    if k == 1:
        return 1 if n >= x else 0

    # Initialize a table to store results of subproblems
    dp = [[0 for _ in range(n + 1)] for _ in range(k + 1)]

    # Base case: If n = 0 and k = 0, then 1 way to partition
    dp[0][0] = 1

    # Base case: If n > 0 and k = 0, then no way to partition
    for i in range(1, n + 1):
        dp[0][i] = 0

    # Fill the partition table in bottom up manner
    for i in range(1, k + 1):
        for j in range(1, n + 1):
            if j < i * x:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - i * x]

    return dp[k][n]

def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: If n is less than k times x, no partition is possible
    if n < k * x:
        return 0
    # Base case: If k is 1, there's only one way to partition n, and it must be n itself
    if k == 1:
        return 1 if n >= x else 0
    # Recursive case: Count partitions including at least one part as x and partitions with parts greater than x
    return count_partitions(n - x, k - 1, x) + count_partitions(n, k, x + 1)

def count_partitions(n: int, k: int, x: int) -> int:
    if k == 0:
        return 1 if n == 0 else 0
    if n < k * x:
        return 0
    # Use dynamic programming to store intermediate results
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 1 if i == 0 else 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - x][j - 1] if i - x >= 0 else 0
            dp[i][j] += dp[i - 1][j] - dp[i - x - 1][j] if i - x - 1 >= 0 else dp[i - 1][j]
    return dp[n][k]

