def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: a subset with volume 0 is always possible (empty subset)

    # Iterate over each item
    for volume in volumes:
        # Traverse the dp array backwards to avoid using an item more than once
        for i in range(V, volume - 1, -1):
            if dp[i - volume]:
                dp[i] = True

    # Find the largest volume that can be formed which is less than or equal to V
    for i in range(V, -1, -1):
        if dp[i]:
            return V - i

    return V  # If no items can be fitted, the remaining space is the full capacity of the box

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array where dp[i] will be True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (the empty subset)

    # Iterate over each item's volume
    for volume in volumes:
        # Traverse the dp array backwards to avoid overwriting results from the same iteration
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be formed which is less than or equal to V
    max_fillable_volume = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_fillable_volume = i
            break

    # The minimum remaining space is the total capacity minus the maximum fillable volume
    return V - max_fillable_volume

def calculate_arrangements(n, m, a) -> int:
