def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0  # With 2 or fewer students, they can always form a choir

    left_increasing = [1] * n
    right_increasing = [1] * n

    # Calculate the longest increasing subsequence from the left
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    # Calculate the longest increasing subsequence from the right
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_increasing[i] = right_increasing[i + 1] + 1

    # Find the minimum number of students to remove
    min_students_to_leave = n
    for i in range(n):
        # The total length if we consider heights[i] as the peak
        total_length = left_increasing[i] + right_increasing[i] - 1
        min_students_to_leave = min(min_students_to_leave, n - total_length)

    return min_students_to_leave

